    c0=min(j for i,j in cells); c1=max(j for i,j in cells)
    def fill(r0,r1,c0,c1):
        cols=[5,2,5]
        for k in range(3):
            if k>(r1-r0)//2 or k>(c1-c0)//2: break
            for i in range(r0+k,r1-k+1):
                for j in range(c0+k,c1-k+1):
                    if i in (r0+k,r1-k) or j in (c0+k,c1-k):
                        g[i][j]=cols[k]
        ir0,ir1,ic0,ic1=r0+3,r1-3,c0+3,c1-3
        if ir1>=ir0 and ic1>=ic0:  # any interior remains
            if ir1-1>=ir0+1 and ic1-1>=ic0+1:
                fill(ir0+1,ir1-1,ic0+1,ic1-1)
            elif ir1==ir0 and ic1==ic0:
                g[ir0][ic0]=5
    fill(r0,r1,c0,c1)
    return g

